INSERT INTO SCM_MGR.DM_MOBILE_REPORT_PRODUCT ( DIVISION_ID , VERSION_NO , YYYY , SP_BP_TYPE , PRODUCT_NAME , PRODUCT_DETAIL , MEASURE , MM01, MM02, MM03, MM04, MM05, MM06, MM07, MM08, MM09, MM10, MM11, MM12 , ORI_VERSION_NO , SORT_NO , CREATED_BY , CREATION_DATE , LAST_UPDATED_BY , LAST_UPDATE_DATE ) WITH ISV AS ( SELECT /*+ MATERIALIZE */ DIVISION_ID, ITEM_ID, FORECAST_INFO_BIZ_TYPE, FORECAST_INFO_CELL_PACK_COUNT FROM DM_MST_ITEM_SINGLE_V WHERE DIVISION_ID = :B1 ) SELECT A.DIVISION_ID , :B3 AS VERSION_NO , Y.YYYY AS YYYY , 'SP' AS SP_BP_TYPE , A.PRODUCT_GROUP AS PRODUCT_NAME , CASE WHEN A.PRODUCT_GROUP = '파우치형' THEN NVL(A.ATTRIBUTE1,'-') WHEN A.PRODUCT_GROUP = '원통형' THEN NVL(A.ATTRIBUTE2,'-') ELSE '-' END AS PRODUCT_DETAIL , A.MEASURE , SUM(CASE WHEN SUBSTR(A.YYYYMMDD,1,6) = Y.YYYY || '01' THEN A.QTY ELSE 0 END) AS MM01 , SUM(CASE WHEN SUBSTR(A.YYYYMMDD,1,6) = Y.YYYY || '02' THEN A.QTY ELSE 0 END) AS MM02 , SUM(CASE WHEN SUBSTR(A.YYYYMMDD,1,6) = Y.YYYY || '03' THEN A.QTY ELSE 0 END) AS MM03 , SUM(CASE WHEN SUBSTR(A.YYYYMMDD,1,6) = Y.YYYY || '04' THEN A.QTY ELSE 0 END) AS MM04 , SUM(CASE WHEN SUBSTR(A.YYYYMMDD,1,6) = Y.YYYY || '05' THEN A.QTY ELSE 0 END) AS MM05 , SUM(CASE WHEN SUBSTR(A.YYYYMMDD,1,6) = Y.YYYY || '06' THEN A.QTY ELSE 0 END) AS MM06 , SUM(CASE WHEN SUBSTR(A.YYYYMMDD,1,6) = Y.YYYY || '07' THEN A.QTY ELSE 0 END) AS MM07 , SUM(CASE WHEN SUBSTR(A.YYYYMMDD,1,6) = Y.YYYY || '08' THEN A.QTY ELSE 0 END) AS MM08 , SUM(CASE WHEN SUBSTR(A.YYYYMMDD,1,6) = Y.YYYY || '09' THEN A.QTY ELSE 0 END) AS MM09 , SUM(CASE WHEN SUBSTR(A.YYYYMMDD,1,6) = Y.YYYY || '10' THEN A.QTY ELSE 0 END) AS MM10 , SUM(CASE WHEN SUBSTR(A.YYYYMMDD,1,6) = Y.YYYY || '11' THEN A.QTY ELSE 0 END) AS MM11 , SUM(CASE WHEN SUBSTR(A.YYYYMMDD,1,6) = Y.YYYY || '12' THEN A.QTY ELSE 0 END) AS MM12 , NVL((SELECT V.ORI_VERSION_NO FROM SCM_MGR.DM_MDF_VERSION V WHERE V.DIVISION_ID = :B1 AND V.VERSION_NO = :B3 AND ROWNUM = 1), '-') AS ORI_VERSION_NO , B.DISPLAY_SEQ AS SORT_NO , :B4 AS CREATED_BY , SYSDATE AS CREATION_DATE , :B4 AS LAST_UPDATED_BY , SYSDATE AS LAST_UPDATE_DATE FROM ( SELECT A.DIVISION_ID, A.PRODUCT_GROUP , CASE WHEN A.MEASURE = 'Business_Plan' THEN 'RTF' ELSE A.MEASURE END AS MEASURE , A.YYYYMMDD, A.ATTRIBUTE1, A.ATTRIBUTE2 , CASE WHEN A.MEASURE = 'RTF' AND B.FORECAST_INFO_BIZ_TYPE = 'PACK' AND B.FORECAST_INFO_CELL_PACK_COUNT <> 0 THEN A.QTY * NVL(B.FORECAST_INFO_CELL_PACK_COUNT, 1) ELSE A.QTY END AS QTY FROM DM_PLN_SALES_PLAN_REPORT_C A LEFT OUTER JOIN ISV B ON A.DIVISION_ID = B.DIVISION_ID AND A.ITEM_ID = B.ITEM_ID WHERE A.DIVISION_ID = :B1 AND A.VERSION_NO = :B3 AND A.MEASURE IN ('RTF','Business_Plan','SalesAmt_KRW') UNION ALL SELECT A.DIVISION_ID, A.PRODUCT_GROUP , CASE WHEN A.MEASURE = 'Business_Plan' THEN 'RTF' ELSE A.MEASURE END AS MEASURE , A.YYYYMMDD, A.ATTRIBUTE1, A.ATTRIBUTE2 , CASE WHEN A.MEASURE = 'RTF' AND B.FORECAST_INFO_BIZ_TYPE = 'PACK' AND B.FORECAST_INFO_CELL_PACK_COUNT <> 0 THEN A.QTY * NVL(B.FORECAST_INFO_CELL_PACK_COUNT, 1) ELSE A.QTY END AS QTY FROM DM_PLN_SALES_ETC_REPORT_C A LEFT OUTER JOIN ISV B ON A.DIVISION_ID = B.DIVISION_ID AND A.ITEM_ID = B.ITEM_ID WHERE A.DIVISION_ID = :B1 AND A.VERSION_NO = :B3 AND A.MEASURE IN ('RTF','Business_Plan','SalesAmt_KRW') ) A LEFT OUTER JOIN SCM_ADM_LOOKUP_MASTER_DETAIL B ON A.PRODUCT_GROUP = B.SEGMENT1 AND B.LOOKUP_TYPE = 'REPORT_GROUP2' CROSS JOIN ( SELECT TO_CHAR(TO_NUMBER(:B2 ) - 1) AS YYYY FROM DUAL UNION ALL SELECT :B2 AS YYYY FROM DUAL UNION ALL SELECT TO_CHAR(TO_NUMBER(:B2 ) + 1) AS YYYY FROM DUAL ) Y WHERE 1 = 1 AND A.YYYYMMDD LIKE Y.YYYY || '%' GROUP BY A.DIVISION_ID , A.PRODUCT_GROUP , CASE WHEN A.PRODUCT_GROUP = '파우치형' THEN NVL(A.ATTRIBUTE1,'-') WHEN A.PRODUCT_GROUP = '원통형' THEN NVL(A.ATTRIBUTE2,'-') ELSE '-' END , A.MEASURE , B.DISPLAY_SEQ , Y.YYYY